const hoje = new Date();
hoje.setHours(0,0,0,0);
const fmt = d => d.toISOString().split('T')[0];
const add = n => { const d = new Date(hoje); d.setDate(d.getDate()+n); return fmt(d); };
return [{ json: { d7: add(7), d15: add(15), d40: add(40) } }];

const contratos = $input.first().json;
if (!Array.isArray(contratos) || contratos.length === 0) return [];

const hoje = new Date(); hoje.setHours(0,0,0,0);
const fmt = v => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);
const fmtData = s => new Date(s+'T12:00:00').toLocaleDateString('pt-BR');

const saidas = [];

for (const c of contratos) {
  const venc = new Date(c.data_vencimento+'T12:00:00');
  const dias = Math.round((venc - hoje) / 86400000);
  const emoji = dias <= 7 ? '🔴' : dias <= 15 ? '🟠' : '🟡';
  const label = dias <= 7 ? 'URGENTE — Vence em 7 dias' : dias <= 15 ? 'ATENÇÃO — Vence em 15 dias' : 'AVISO — Vence em 40 dias';

  const msg = `${emoji} *${label}*\n\n` +
    `📄 *Contrato:* ${c.numero_contrato}\n` +
    `🏢 *Fornecedor:* ${c.fornecedor}\n` +
    `🏛️ *Secretaria:* ${c.secretarias?.nome || ''}\n` +
    `📝 *Objeto:* ${c.objeto}\n` +
    `💰 *Valor:* ${fmt(c.valor_total)}\n` +
    `📅 *Vencimento:* ${fmtData(c.data_vencimento)}\n` +
    `⏳ *Dias restantes:* ${dias}\n\n` +
    `Acesse o ContratoPro e tome as providências necessárias.`;

  if (c.fiscal_whatsapp) saidas.push({ json: { whatsapp: c.fiscal_whatsapp, destinatario: c.fiscal_nome, mensagem: msg } });
  if (c.secretario_whatsapp && c.secretario_whatsapp !== c.fiscal_whatsapp)
    saidas.push({ json: { whatsapp: c.secretario_whatsapp, destinatario: c.secretario_nome, mensagem: msg } });
}

return saidas;
